1	const PROCESSING_FEE = 5;
2	
3	// Modifiers are percentages OF THE UNMODIFIED BASE PREMIUM, summed additively
4	// rather than compounded — see the spec's integration examples, where a cursed
5	// sword is 100 base + 50 curse + 10 first insurance (10% of 100, not of 150).
6	//
7	// Rates are kept as integer percents and divided only once, at the point of
8	// use: percentOf(100, 10) is (100 * 10) / 100 = exactly 10, whereas a 0.1
9	// multiplier would give 10.000000000000002 and inflate Math.ceil.
10	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
11	
12	const FIRST_INSURANCE_PERCENT = 10;
13	const FOLLOW_UP_PERCENT = 15;
14	const LOYALTY_PERCENT = 20;
15	const LOYALTY_THRESHOLD_YEARS = 2;
16	const CURSE_PERCENT = 50;
17	const HIGH_ENCHANTMENT_PERCENT = 30;
18	const HIGH_ENCHANTMENT_THRESHOLD = 5;
19	
20	// The price list prices each main item individually...
21	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	  potion: 40,
26	};
27	
28	// ...whereas every component is flat-rated at the same base premium,
29	// regardless of which component it is.
30	const COMPONENT_BASE_PREMIUM = 25;
31	const COMPONENT_TYPES = ["rune", "moonstone"];
32	
33	const BLOCK_SIZE = 3;
34	const BLOCK_BASE_PREMIUM = 60;
35	
36	// Claims are settled against the insured VALUE of an item, which the price
37	// list states separately from its base premium.
38	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
39	  sword: 1000,
40	  amulet: 600,
41	  staff: 800,
42	  potion: 400,
43	};
44	const COMPONENT_INSURANCE_VALUE = 250;
45	
46	const DEDUCTIBLE = 100;
47	const CAP_MULTIPLE = 2;
48	
49	const BASE_PREMIUMS: Record<string, number> = {
50	  ...MAIN_ITEM_BASE_PREMIUMS,
51	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
52	};
53	
54	const INSURANCE_VALUES: Record<string, number> = {
55	  ...MAIN_ITEM_INSURANCE_VALUES,
56	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_INSURANCE_VALUE])),
57	};
58	
59	type Item = { type: string; cursed?: boolean; enchantment?: number };
60	type Damage = { itemType: string; amount: number };
61	type Incident = { cause: string; damages: Damage[] };
62	type QuoteStep = { op: "quote"; items: Item[] };
63	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
64	type Step = QuoteStep | ClaimStep;
65	type Customer = { yearsWithMHPCO: number };
66	type Scenario = { customer: Customer; steps: Step[] };
67	
68	const countByType = (items: Item[]): Map<string, number> =>
69	  items.reduce(
70	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
71	    new Map<string, number>(),
72	  );
73	
74	// A building block of exactly 3 alike components is offered at a special
75	// rate; any other count is priced per component.
76	const basePremiumForType = (type: string, count: number): number =>
77	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
78	
79	const stepBasePremium = (step: QuoteStep): number =>
80	  [...countByType(step.items)].reduce(
81	    (total, [type, count]) => total + basePremiumForType(type, count),
82	    0,
83	  );
84	
85	// Components carry no enchantment level at all, so a missing value is
86	// simply not highly enchanted.
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
89	
90	// Item-specific modifiers apply to the base premium of the affected item,
91	// so they are computed per item rather than from the grouped totals. A
92	// cursed, highly enchanted item takes both surcharges.
93	const itemSurcharge = (item: Item): number => {
94	  const basePremium = BASE_PREMIUMS[item.type];
95	  const curseSurcharge = item.cursed ? percentOf(basePremium, CURSE_PERCENT) : 0;
96	  const enchantmentSurcharge = isHighlyEnchanted(item)
97	    ? percentOf(basePremium, HIGH_ENCHANTMENT_PERCENT)
98	    : 0;
99	
100	  return curseSurcharge + enchantmentSurcharge;
101	};
102	
103	const totalItemSurcharges = (items: Item[]): number =>
104	  items.reduce((total, item) => total + itemSurcharge(item), 0);
105	
106	const isLongStanding = (customer: Customer): boolean =>
107	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
108	
109	// Policy-wide modifiers apply to the policy base premium (the sum of all
110	// item base premiums). Discounts are negative terms in the same sum.
111	const netPolicyModifier = (
112	  basePremium: number,
113	  customer: Customer,
114	  isFollowUpContract: boolean,
115	): number => {
116	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
117	  const loyaltyDiscount = isLongStanding(customer)
118	    ? percentOf(basePremium, LOYALTY_PERCENT)
119	    : 0;
120	  const followUpDiscount = isFollowUpContract
121	    ? percentOf(basePremium, FOLLOW_UP_PERCENT)
122	    : 0;
123	
124	  return firstInsurance - loyaltyDiscount - followUpDiscount;
125	};
126	
127	// Rounded in the MHPCO's favour: premiums round up.
128	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUpContract: boolean): number => {
129	  const basePremium = stepBasePremium(step);
130	
131	  return Math.ceil(
132	    basePremium +
133	      totalItemSurcharges(step.items) +
134	      netPolicyModifier(basePremium, customer, isFollowUpContract) +
135	      PROCESSING_FEE,
136	  );
137	};
138	
139	// The policy's cap is twice the insurance sum of everything it covers.
140	const policyCap = (policy: QuoteStep): number =>
141	  CAP_MULTIPLE *
142	  policy.items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
143	
144	// A deductible applies per damage event, i.e. once per damaged item.
145	// Rounded in the MHPCO's favour: payouts round down.
146	const damagePayout = (damage: Damage): number =>
147	  Math.floor(damage.amount - DEDUCTIBLE);
148	
149	export const runScenario = (scenario: unknown): { results: unknown[] } => {
150	  const { customer, steps } = scenario as Scenario;
151	  const capRemaining = new Map<number, number>();
152	
153	  // Every contract after the customer's first is a follow-up.
154	  const results = steps.map((step, index) => {
155	    if (step.op === "claim") {
156	      const policy = steps[step.policy] as QuoteStep;
157	      const remaining = capRemaining.get(step.policy) ?? policyCap(policy);
158	      const payout = step.incident.damages.reduce(
159	        (total, damage) => total + damagePayout(damage),
160	        0,
161	      );
162	
163	      capRemaining.set(step.policy, remaining - payout);
164	
165	      return { payout, remainingCap: remaining - payout };
166	    }
167	
168	    return { premium: quotePremium(step, customer, index > 0) };
169	  });
170	
171	  return { results };
172	};
