// A deductible applies per damage event, i.e. once per damaged item.
// Rounded in the MHPCO's favour: payouts round down.
const damagePayout = (damage: Damage): number =>
  Math.floor(damage.amount - DEDUCTIBLE);

// A claim is settled against the cap of the policy it names, which is
// consumed across successive claims on that policy.
const settleClaim = (
  step: ClaimStep,
  steps: Step[],
